  _resourceData(){this._appCfg=this._appCfg||{};let d=this._appCfg.resourcePlans;if(!d||typeof d!=='object')d=this._appCfg.resourcePlans={teams:[]};if(!Array.isArray(d.teams))d.teams=[];return d;}
