  _resourceCoreValues(t,lv){const sum={};this._resourceKeys().forEach(k=>sum[k]=0);(t&&t.cores||[]).filter(x=>!lv||x.lv===lv).forEach(x=>this._resourceKeys().forEach(k=>sum[k]+=Number(k==='rebar'&&x[k]==null?x.concrete:x[k])||0));return sum;}
