  /* delay 判断: 到本月为止, 该区任一活动"累计计划 > 累计完成"(actCarry.balance>0)= 本该做完的还欠着 = 延误 */
  zoneDelayed(lv,z,m){const zmk=z.mk||z.lid;const mi=this.ACT_MONTHS.indexOf(m);if(mi<0)return false;return this._actMeta().some(a=>{const cg=this.actCarry(lv,zmk,a.id,mi);return cg.hasData&&cg.balance>0;});}
  /* 该区是否有"填了 Done 却缺总量/计划"的活动(算不出百分比, 需要 admin 补 Total/Plan) */
  _zoneNeedScope(lv,z){try{const zmk=z.mk||z.lid;const M=this.ACT_MONTHS||[];const acts=(this._actList?this._actList(lv,z):[]).filter(a=>a.custom||this._actApplies(a.id,lv,z));return acts.some(a=>{let tot=a.total;/* 普通板没有 Slab plan 时，以 zone 面积作为实际浇筑的完整 scope。 */if((tot==null||tot<=0)&&!z._mslab&&['slab','slab_top','slab_pile'].includes(a.id))tot=+(z.area||z.a||0);if(tot!=null&&tot>0)return false;let done=0;M.forEach(m=>{const v=this.actDoneMonth(lv,zmk,a.id,m);if(v!=null)done+=(+v||0);});return done>0;});}catch(e){return false;}}
  /* 月度地图状态 — 计划线(CSV 各月计划量)和实际线(各月实际完成量)分开算, 实际优先于计划。
     返回 state: fin_earlier(更早已完成,灰绿保留) / act_finish(本月实际完成) / act_prog(实际进行中)
                / plan_finish(本月计划完成) / plan_this(本月计划开始或在做) / none(本月无工作) */
  PLAN_COLORS(){return {fin_earlier:'#5f6368',act_finish:'#5f6368',act_prog:'#d7ad58',plan_finish:'#6259bd',plan_this:'#2f7f61',none:'#ffffff'};}
