        x.fillStyle='#202938';x.font='700 14px Arial';x.fillText(String(r.label)+(r.group?'  ('+r.group+')':''),cols[1],y+25);
        x.fillStyle='#667085';x.font='13px Arial';x.fillText(r.cat,cols[2],y+25);
