    const _mv=this._marineViewScope(),_viewCount=_mv?_mv.zones.length:arr.length,_viewTitle=_mv?('L1 · Marine · '+_mv.label):(this.curLevel+' · '+this.DATA.levels[this.curLevel].title);
    const _openCmts=this._levelOpenCmts(this.curLevel),_doneCmts=this._levelDoneCmts(this.curLevel),_pmN=_openCmts.filter(c=>c.to==='PM').length,_plN=_openCmts.filter(c=>c.to==='Planning').length;
    const _cmtBadges=_openCmts.length?`<button class="level-cmt-badge level-cmt-toggle has-open" title="Open comments · PM ${_pmN} · Planning ${_plN}">${_openCmts.length}</button>`:'';
