    this.root.querySelector('#sideTitle').innerHTML=`<span>${this.esc(_viewTitle)}</span><span class="side-hd-right"><span class="pill">${_viewCount} zones</span>${_cmtBadges}${_doneBadges}${(!_openCmts.length&&!_doneCmts.length)?'<button class="level-cmt-badge level-cmt-toggle" title="No comments">0</button>':''}</span>`;
    let s=`<div class="listhint" style="font-size:11.5px;color:var(--faint);padding:16px 6px;line-height:1.7">Select a zone on the map to view its details.<br><span style="font-size:10px">${_viewCount} zones in this view · switch <b>Colour</b> to <b>Planned (month)</b> for the monthly plan overview.</span></div>`;
    if(this.colorMode==='plan'){
      const m=this.planMonth(), M=this.visMonths(), mi=M.indexOf(m), curL=this.actCurLabel();
      let planned=(_mv?_mv.zones:arr).map((z,idx)=>({z,items:this.zonePlanItems(this.curLevel,z,m),k:this.zid(z),sub:(_mv&&_mv.kind!=='ZC')?(_mv.kind+'|'+idx):null})).filter(x=>x.items.length);
      if(!_mv&&this.curLevel==='L1'&&(this.filterCat==='all'||this.filterCat==='MA')&&this.SUBZONES&&this.SUBZONES.L1){   /* 只有 All/Marine 才附加 C/P；选择 EB/NB 时绝不混入 Marine */
        const _subItems=(label)=>{const zmk='L1|'+label,mi=this.ACT_MONTHS.indexOf(m),out=[];this._actMeta().forEach(a=>{if(this.actHidden('L1',zmk,a.id))return;const p=this.actPlan('L1',zmk,a.id,m);if(p!=null&&p>0){const d=this.actDoneMonth('L1',zmk,a.id,m)||0,cg=mi>=0?this.actCarry('L1',zmk,a.id,mi):null;out.push({label:a.label,qty:p,unit:a.unit,done:d,owed:cg?Math.max(0,cg.balance):Math.max(0,p-d),achieved:cg?cg.balance<=0:d>=p});}});return out;};
        ['C','P'].forEach(kind=>{(this.SUBZONES.L1[kind]||[]).forEach((sz,idx)=>{const items=_subItems(sz.label);if(items.length)planned.push({z:{label:sz.label,cat:'MA',crit:false},items,k:sz.label,sub:kind+'|'+idx});});});
      }
      planned.sort((a,b)=>this.esc(a.z.label).localeCompare(this.esc(b.z.label)));
      const opts=M.map(mm=>`<option value="${mm}" ${mm===m?'selected':''}>${mm}${mm===curL?' (now)':''}</option>`).join('');
      s=`<div class="planhd"><div class="t">📅 Monthly plan · ${this.esc(_mv?('L1 · '+_mv.label):this.curLevel)}</div><div class="plan-monthbar"><button class="hbtn planm-nav" data-dir="-1" ${mi<=0?'disabled':''}>‹</button><select class="plan-month">${opts}</select><button class="hbtn planm-nav" data-dir="1" ${mi>=M.length-1?'disabled':''}>›</button></div><div class="plan-sub"><b style="color:var(--accent)">${planned.length}</b> of ${_viewCount} zones have planned work in <b>${m}</b> · <span style="color:#6d6f74"><b style="color:#8c968f">■ done (stays)</b> · <b style="color:#166b47">■ done this month</b> · <b style="color:#c98f1e">■ in progress</b> · <b style="color:#3f38a6">■ plan finish</b> · <b style="color:#a7a2e8">■ planned</b></span></div></div>`;
      if(!planned.length){ s+=`<div class="empty" style="padding:16px 6px">No zones have planned activity in ${m}.</div>`; }
      else { s+=planned.map(x=>{const z=x.z;const _tag=x.sub?` <span style="font-size:9px;font-weight:700;color:var(--faint)">· ${x.sub[0]==='P'?'Podium':'sub-div'}</span>`:'';return `<div class="planzone" data-k="${this.esc(x.k)}"${x.sub?` data-sub="${this.esc(x.sub)}"`:''}><div class="pz-nm"><span class="sw" style="background:${(this.CAT[z.cat]||this.CAT.NB).c}"></span>${this.esc(z.label)}${z.crit?' <span style="color:var(--crit)">◆</span>':''}${_tag}</div><div class="pz-acts">${x.items.map(it=>{const u=it.unit?' '+this.esc(it.unit):'',result=it.achieved?'<span style="color:var(--done)">Achieved</span>':'<span style="color:var(--crit)">Outstanding '+this.fmt(it.owed)+u+'</span>';return `<div class="pz-act" style="align-items:flex-start"><span>${this.esc(it.label)}<small style="display:block;margin-top:2px;color:var(--faint);font-size:8.5px">Plan ${this.fmt(it.qty)}${u} · Actual ${this.fmt(it.done)}${u}</small></span><b>${result}</b></div>`;}).join('')}</div></div>`;}).join(''); }
    }
    if(this._levelCmtOpen)s=this._levelCmtPanel(this.curLevel)+s;
