    host.querySelectorAll('.sch-total').forEach(el=>{ const c=()=>this.setActTotal(lv,zmk,el.dataset.a,el.value,z); el.addEventListener('change',c); el.addEventListener('keydown',e=>{if(e.key==='Enter')el.blur();}); });
